import{z as o,x as s,o as B,c as d,q as A,j as n,D as e,d as t,s as r,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"注意力头剪枝","description":"","frontmatter":{"title":"注意力头剪枝","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/attention-head-pruning.md","filePath":"llm/attention-head-pruning.md","lastUpdated":1791063341000}'),D={name:"llm/attention-head-pruning.md"};function p(m,E,h,u,V,C){const l=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=A('<h1 id="注意力头剪枝" tabindex="-1">注意力头剪枝 <a class="header-anchor" href="#注意力头剪枝" aria-label="Permalink to &quot;注意力头剪枝&quot;">​</a></h1><div class="epigraph"><p>推理时关掉一部分头，翻译或编码往往几乎不掉；那是静态冗余，不是 Deja Vu 那种逐步预测。</p><footer>—— Michel, Levy, Neubig, Are Sixteen Heads Really Better than One?, NeurIPS 2019；Voita et al., ACL 2019</footer></div><p><a href="/llm/deja-vu-sparsity">上一课</a> 每步预测保留哪些头。<a href="/llm/attention-head-roles">头的功能分化</a> 已经给出静态故事：少数头干活，许多头平坦。本课动手：<strong>一次性删头</strong>，留下的模型仍是标准 MHA，只是头数变少。缺口是重要性怎么估、删完要不要愈合，以及它和 GQA 不是同一件事。后课离开稀疏，进入低秩分解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Michel 等人在翻译模型上逐头置零，发现不少头对 BLEU 几乎无贡献，甚至一层只留一头仍能工作。Voita 等人用门控看到头的专门化与可剪性。LLM 上同样的实验更贵，但逻辑不变：多头提供槽位，槽位填不满。缺口是把「可剪」写成部署动作：删哪些、\\(d_h\\) 是否跟着变、KV 缓存是否按头数下降。</p><p>GQA 从设计上共享 K/V，是训练时的形状选择。剪头是训练后删已经学开的头。把剪完的 32 头模型叫「变成 GQA」是错的——GQA 的组结构与随机删头留下的不规则子集不同。</p><p><span class="marginnote">重要性不能只看注意力权重熵。平坦的头可能仍通过值向量做常偏置；应对输出做干预，与专精化分析课同一纪律。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>校准或验证集上，对每个头做置零（或缩放到 0），看损失 / 下游跌点，贪心删跌点最小的头，或按层保留固定个数。删完可选短微调或 <a href="/llm/lora">LoRA</a> 愈合；one-shot 在中等比例往往可接受，激进删头需要愈合。实现上从 \\(W_Q,W_K,W_V,W_O\\) 去掉对应列块，KV 缓存宽度下降，这是真加速，不依赖稀疏核。</p><p><span class="marginnote">数字实例：32 头剪到 24 头，KV 缓存直接省 25%。以常见的每头 \\(d_h=128\\)、fp16 存储算，每层每个 token 的 KV 是 \\(2\\times128\\times32\\times2\\,\\text{B}=16\\) KB；剪到 24 头降为 12 KB。上下文 32K、40 层时，这笔账就是上 GB 的显存差别——这也是剪头在 decode 上是真加速的原因。</span></p><p>与 2:4 / Wanda 叠：先定头数再对留下的投影做权重稀疏，校准必须在已剪头的图上做。</p>',11)),(B(),n(i,null,{default:e(()=>[r(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%90%84%E5%A4%B4%22%5D%20--%3E%20INTV%5B%22%E7%BD%AE%E9%9B%B6%E5%B9%B2%E9%A2%84%22%5D%0A%20%20INTV%20--%3E%20RANK%5B%22%E6%8C%89%E8%B7%8C%E7%82%B9%E6%8E%92%E5%BA%8F%22%5D%0A%20%20RANK%20--%3E%20DROP%5B%22%E5%88%A0%E9%99%A4%E4%BD%8E%E8%B4%A1%E7%8C%AE%E5%A4%B4%22%5D%0A%20%20DROP%20--%3E%20HEAL%5B%22%E5%8F%AF%E9%80%89%E7%9F%AD%E5%BE%AE%E8%B0%83%20%2F%20LoRA%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"多头是并列子空间。冗余头的 \\(W_Q\\)/\\(W_K\\) 张成的方向与其它头高度相关，删掉后 SDPA 的加权和几乎不变。孤点头（归纳头、位置头）干预跌点大，对应 MoE 课的孤点专家，不可先删。层间不均：底层更偏位置、上层更偏内容，应按层配额而不是全局一个阈值，否则底层被删光。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：「孤点头」就是整个网络里只有一个头会干某件活的头，比如归纳头负责「看到上文重复的片段就把后续内容抄回来」。删冗余头像裁掉重身的合唱声部，少一个还有别人唱同一句；删孤点头像裁掉唯一的鼓手，PPL 表面看只涨一点，长文本的自检能力却先塌。")],-1)),E[6]||(E[6]=a("p",null,"Decode 收益主要来自 KV 字节与 QKV GEMM 变瘦，不是来自 SDPA 的 \\(n^2\\) 魔术——头数减半，SDPA FLOPs 大致减半，但长上下文仍平方。不要宣称剪头解决长上下文。",-1)),E[7]||(E[7]=a("p",null,[a("span",{class:"marginnote"},"常见误区：初学者容易以为「剪头」和「GQA」是一回事，反正都是头变少。实际上 GQA 是训练前就设计好几组头共用一份 K/V，结构规整；剪头是训练后从 32 头里删出 24 头，留下的是不规则子集，每个头仍有自己独立的 K/V。把剪过的模型宣传成「等价于 GQA」在形状和显存账上都对不上。")],-1)),(B(),n(i,null,{default:e(()=>[r(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%80%90%E5%A4%B4%E7%BD%AE%E9%9B%B6%E6%B5%8B%E8%B7%8C%E7%82%B9%22%5D%20--%3E%20RD%5B%22%E8%B7%8C%E7%82%B9%E7%BA%A6%E7%AD%89%E4%BA%8E%200%EF%BC%9A%E5%86%97%E4%BD%99%E5%A4%B4%22%5D%0A%20%20H%20--%3E%20LD%5B%22%E8%B7%8C%E7%82%B9%E6%98%8E%E6%98%BE%EF%BC%9A%E5%AD%A4%E7%82%B9%E5%A4%B4%22%5D%0A%20%20RD%20--%3E%20DEL%5B%22%E6%96%B9%E5%90%91%E4%B8%8E%E5%88%AB%E7%9A%84%E5%A4%B4%E9%AB%98%E5%BA%A6%E7%9B%B8%E5%85%B3%EF%BC%8C%E5%88%A0%E5%90%8E%E5%8A%A0%E6%9D%83%E5%92%8C%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%98%22%5D%0A%20%20DEL%20--%3E%20KV%5B%22%E5%A4%B4%E6%95%B0%E4%B8%8B%E9%99%8D%EF%BC%9AKV%20%E7%BC%93%E5%AD%98%E4%B8%8E%20QKV%20GEMM%20%E5%8F%98%E7%98%A6%22%5D%0A%20%20LD%20--%3E%20KEEP%5B%22%E5%BD%92%E7%BA%B3%E5%A4%B4%E3%80%81%E4%BD%8D%E7%BD%AE%E5%A4%B4%E7%AD%89%E5%94%AF%E4%B8%80%E5%B9%B2%E6%B4%BB%E7%9A%84%E5%A4%B4%22%5D%0A%20%20KEEP%20--%3E%20QUOTA%5B%22%E6%8C%89%E5%B1%82%E9%85%8D%E9%A2%9D%E4%BF%9D%E6%8A%A4%EF%BC%8C%E4%B8%8D%E8%AE%BE%E5%85%A8%E5%B1%80%E9%98%88%E5%80%BC%22%5D%0A%20%20KV%20--%3E%20LIMIT%5B%22%E9%95%BF%E4%B8%8A%E4%B8%8B%E6%96%87%E7%9A%84%E5%B9%B3%E6%96%B9%E9%A1%B9%E4%BB%8D%E5%9C%A8%EF%BC%8C%E5%89%AA%E5%A4%B4%E4%B8%8D%E8%A7%A3%E5%86%B3%E9%95%BF%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要按可视化「好看」删头。不要在 RL 后的推理模型上照搬预训练的头排名——<a href="/llm/grpo">GRPO</a> 会改写头的用法，须重测。激进剪头伤长链自检，比伤短 PPL 更早。下一课对留下的稠密矩阵做低秩分解，删除的是秩而不是头。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>头剪枝是静态结构化删除，KV 与 QKV 变瘦，有密核加速。</li><li>用干预跌点排序，不要用注意力图故事。</li><li>按层配额保护孤点头；与 GQA 设计不是同一形状。</li><li>RL / 指令后必须重测头重要性。</li><li>出处：Michel et al., NeurIPS 2019；Voita et al., ACL 2019。</li></ul>',4))])}const f=o(D,[["render",p]]);export{_ as __pageData,f as default};
